source('mp10_hypothesis_followup_v2/scripts/common.R');suppressPackageStartupMessages(library(GSVA))
b<-qread(file.path(OLD,'objects/pseudobulk.qs'),nthreads=1);mm<-qread(file.path(V1,'objects/scoring_matrices.qs'),nthreads=1)$matrices[['Epi_all']];pr<-mm$profiles;ref<-pr[profile_type=='Epi_all'&main_patient&n_cells>=50,profile_id];de<-as.matrix(b$detected_cells[rownames(mm$logCPM),ref,drop=FALSE]);de<-sweep(de,2,pr[match(ref,profile_id),n_cells],'/');features<-data.table(gene=rownames(mm$logCPM),mean_logCPM=rowMeans(mm$logCPM[,ref,drop=FALSE]),median_detection=apply(de,1,median));features[,`:=`(z_expression=as.numeric(scale(mean_logCPM)),z_detection=as.numeric(scale(median_detection)))];put(features,'gene_matching_reference.tsv.gz');sets<-lapply(split(rd('official_gene_sets.tsv.gz')$gene,rd('official_gene_sets.tsv.gz')$signature),unique);out<-list();memb<-list();deltas<-list()
for(mask in c('Full','M20')){
 mat<-mm$logCPM[!rownames(mm$logCPM)%in%if(mask=='M20')M20 else character(),,drop=FALSE];a<-intersect(sets$CHOL_SYNTH,rownames(mat));bb<-intersect(sets$FA_ACYL_COA,rownames(mat));k<-min(length(a),length(bb));stopifnot(k>=5);ss<-list();set.seed(123)
 for(i in 1:200){small<-if(length(a)<=length(bb))a else bb;large<-if(length(a)<=length(bb))bb else a;small<-sample(sort(small));pairs<-list();remaining<-large
  for(j in seq_along(small)){g<-small[j];f<-features[match(remaining,gene)];u<-features[gene==g];distance<-(f$z_expression-u$z_expression)^2+(f$z_detection-u$z_detection)^2;best<-which(distance==min(distance));sel<-best[sample.int(length(best),1)];h<-remaining[sel];pairs[[j]]<-data.table(repetition=i,mask=mask,small_gene=g,matched_gene=h,distance=sqrt(distance[sel]));remaining<-setdiff(remaining,h)}
  pp<-rbindlist(pairs);aa<-if(length(a)<=length(bb))pp$small_gene else pp$matched_gene;ff<-if(length(a)<=length(bb))pp$matched_gene else pp$small_gene;ss[[paste0('C',i)]]<-aa;ss[[paste0('F',i)]]<-ff;pp[,`:=`(small_source=if(length(a)<=length(bb))'CHOL_SYNTH'else'FA_ACYL_COA',n_matched=k)];memb[[paste(mask,i)]]<-pp
 }
 rs<-gsva(ssgseaParam(mat,ss,minSize=5,alpha=.25,normalize=FALSE),verbose=FALSE,BPPARAM=BiocParallel::SerialParam());cent<-rowMeans(rs[,ref,drop=FALSE]);sds<-apply(rs[,ref,drop=FALSE],1,sd);zs<-sweep(sweep(rs,1,cent,'-'),1,sds,'/');ok<-pr[main_patient&n_cells>=50&profile_type%in%c('H05','L50'),.N,by=sample_uid][N==2,sample_uid];hi<-pr[profile_type=='H05'&sample_uid%in%ok][order(sample_uid)];lo<-pr[profile_type=='L50'&sample_uid%in%ok][order(sample_uid)];stopifnot(identical(hi$sample_uid,lo$sample_uid))
 for(i in 1:200){dc<-zs[paste0('C',i),hi$profile_id]-zs[paste0('C',i),lo$profile_id];df<-zs[paste0('F',i),hi$profile_id]-zs[paste0('F',i),lo$profile_id];dd<-dc-df;n<-length(dd);beta<-mean(dd);se<-sqrt(sum((dd-beta)^2)/(1-1/n)^2/n^2);out[[paste(mask,i)]]<-data.table(mask=mask,repetition=i,n_genes=k,n_specimens=n,beta=beta,SE_HC3=se,CI_low=beta-qt(.975,n-1)*se,CI_high=beta+qt(.975,n-1)*se,P_diagnostic_only=2*pt(-abs(beta/se),n-1),CHOL_reference_center=cent[paste0('C',i)],CHOL_reference_SD=sds[paste0('C',i)],FA_reference_center=cent[paste0('F',i)],FA_reference_SD=sds[paste0('F',i)]);deltas[[paste(mask,i)]]<-data.table(mask=mask,repetition=i,sample_uid=hi$sample_uid,dataset=hi$dataset,delta_CHOL=dc,delta_FA=df,D=dd)}
 cat('MATCHED',mask,k,'\n')
}
z<-rbindlist(out);put(z,'matched_gene_D_results.tsv');put(rbindlist(memb),'matched_gene_membership.tsv.gz');put(rbindlist(deltas),'matched_gene_specimen_deltas.tsv.gz');put(z[,.(n_repetitions=.N,n_genes=first(n_genes),n_specimens=first(n_specimens),median_D=median(beta),q025_D=quantile(beta,.025),q975_D=quantile(beta,.975),fraction_D_positive=mean(beta>0),fraction_CI_above0=mean(CI_low>0),interpretation='dependent gene-matching diagnostics, not 200 biological replicates or independent P values'),by=mask],'matched_gene_D_summary.tsv');thread_audit('matched_genes_complete')
